import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type StrikethroughQuoteProps = Record<string, any>;

const StrikethroughQuote: React.FC<StrikethroughQuoteProps> = ({
  backgroundColor = "#f0f0f0",
  transparentBackground = false,
  durationInSeconds = 5,
  primaryText = "Don't obsess over algorithms.",
  secondaryText = "Obsess over people.",
  textColor = "#000000",
  strikeColor = "#cc0000",
  fontSize = 70,
  strikeHeight = 8,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Theme Logic ---
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Create a subtle vignette effect if background is not transparent
  const backgroundStyle: React.CSSProperties = {
    backgroundColor: bgColor,
    background: transparentBackground 
      ? undefined 
      : `radial-gradient(circle at center, ${backgroundColor} 0%, #d4d4d4 100%)`,
    fontFamily: "Montserrat",
  };

  // --- Animation Timings ---
  const startDelay = 10;
  const strikeDelay = 25;
  const secondaryDelay = 45;

  // 1. Primary Text Entrance (Fade + Slide Up)
  const primaryEntrance = spring({
    frame: frame - startDelay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });
  
  const primaryOpacity = interpolate(primaryEntrance, [0, 1], [0, 1]);
  const primaryTranslateY = interpolate(primaryEntrance, [0, 1], [30, 0]);

  // 2. Strikethrough Animation (Grow Width)
  const strikeProgress = spring({
    frame: frame - strikeDelay,
    fps,
    config: { damping: 15, stiffness: 80, mass: 0.8 },
  });
  
  // Interpolate width from 0% to 105% (slightly wider than text)
  const strikeWidth = interpolate(strikeProgress, [0, 1], [0, 105]); 

  // 3. Secondary Text Entrance (Fade + Slide Up)
  const secondaryEntrance = spring({
    frame: frame - secondaryDelay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const secondaryOpacity = interpolate(secondaryEntrance, [0, 1], [0, 1]);
  const secondaryTranslateY = interpolate(secondaryEntrance, [0, 1], [30, 0]);


  return (
    <AbsoluteFill style={backgroundStyle}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
          padding: "0 40px",
          textAlign: "center",
        }}
      >
        {/* Wrapper for Primary Text + Strikethrough */}
        <div style={{ position: "relative", display: "inline-block" }}>
          
          {/* Primary Text */}
          <h1
            style={{
              margin: 0,
              color: textColor,
              fontSize: fontSize,
              fontWeight: 700,
              opacity: primaryOpacity,
              transform: `translateY(${primaryTranslateY}px)`,
              position: "relative",
              zIndex: 1,
            }}
          >
            {primaryText}
          </h1>

          {/* Strikethrough Line */}
          <div
            style={{
              position: "absolute",
              top: "55%", // Optically centered usually sits slightly lower than mathematical center for text
              left: "-2.5%", // Center the 105% width
              height: strikeHeight,
              backgroundColor: strikeColor,
              width: `${strikeWidth}%`,
              borderRadius: "4px",
              zIndex: 2, // Sit on top of text
              transform: "translateY(-50%)",
              opacity: primaryOpacity, // Fade in with text, but width animates separately
            }}
          />
        </div>

        {/* Secondary Text */}
        <h1
          style={{
            margin: "20px 0 0 0",
            color: textColor,
            fontSize: fontSize,
            fontWeight: 700,
            opacity: secondaryOpacity,
            transform: `translateY(${secondaryTranslateY}px)`,
          }}
        >
          {secondaryText}
        </h1>
      </div>
    </AbsoluteFill>
  );
};

export default StrikethroughQuote;